import json
import re

def parse_script(text):
    nodes_dict = {}
    edges = []

    blocks = re.split(r'\n\s*\n*(?=\[)', text.strip())

    for block in blocks:
        lines = [l.strip() for l in block.split('\n') if l.strip()]
        if not lines: continue

        header_match = re.match(r'\[(.*?)\]', lines[0])
        if not header_match: continue
        node_id = header_match.group(1)

        content_lines = lines[1:]
        is_choice = any(re.match(r'^\d+\.', l) for l in content_lines)

        if is_choice:
            nodes_dict[node_id] = {"id": node_id, "text": "", "speaker": "", "type": "choice"}
            for line in content_lines:
                m = re.match(r'^\d+\.\s*(.*?)\s*->\s*(.*)$', line)
                if m:
                    edges.append({"from": node_id, "to": m.group(2).strip(), "text": m.group(1).strip()})
        else:
            for line in content_lines:
                m = re.match(r'^(.*?):\s*(.*?)\s*->\s*(.*)$', line)
                if m:
                    nodes_dict[node_id] = {"id": node_id, "text": m.group(2).strip(), "speaker": m.group(1).strip(), "type": "line"}
                    edges.append({"from": node_id, "to": m.group(3).strip(), "text": ""})
                    break
            else:
                if node_id not in nodes_dict:
                    nodes_dict[node_id] = {"id": node_id, "text": "", "speaker": "", "type": "line"}

    # Ensure all edge targets exist in nodes_dict
    all_targets = set(e['to'] for e in edges)
    for target in all_targets:
        if target not in nodes_dict:
            nodes_dict[target] = {"id": target, "text": "", "speaker": "", "type": "line"}

    # Convert back to list in order of appearance if possible, or just sorted
    # Original order from script is better
    ordered_ids = []
    for block in blocks:
        m = re.match(r'\[(.*?)\]', block.strip())
        if m and m.group(1) not in ordered_ids:
            ordered_ids.append(m.group(1))
    for target in sorted(all_targets):
        if target not in ordered_ids:
            ordered_ids.append(target)

    final_nodes = [nodes_dict[nid] for nid in ordered_ids if nid in nodes_dict]

    return {"nodes": final_nodes, "edges": edges}

def main():
    with open('/app/script.txt', 'r') as f:
        content = f.read()
    result = parse_script(content)
    with open('/app/dialogue.json', 'w') as f:
        json.dump(result, f, indent=2)
    with open('/app/dialogue.dot', 'w') as f:
