        for node in result['nodes']:
            label = f"{node['speaker']}: {node['text']}" if node['speaker'] else node['text']
            label = label.replace('"', '\\"')
            f.write(f'  "{node["id"]}" [label="{node["id"]}\\n{label}", shape=box];\n')
        for edge in result['edges']:
            f.write(f'  "{edge["from"]}" -> "{edge["to"]}" [label="{edge["text"]}"];\n')
        f.write('}\n')

if __name__ == "__main__":
    main()
